             Assert.IsType<ViewResult>(result);
         }

         [Fact]
         public void Edit_POST_WithInvalidFileExtension_ReturnsViewWithError()
         {
             TestHelpers.SeedCourses(_context);
             var course = _context.Courses.AsNoTracking().First();

             var fileMock = new Mock<IFormFile>();
             fileMock.Setup(f => f.FileName).Returns("test.pdf");
             fileMock.Setup(f => f.Length).Returns(1024);

             var result = _controller.Edit(course, fileMock.Object);

             var viewResult = Assert.IsType<ViewResult>(result);
             Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
         }

         [Fact]
         public void Edit_POST_WithOversizedFile_ReturnsViewWithError()
         {
             TestHelpers.SeedCourses(_context);
             var course = _context.Courses.AsNoTracking().First();

             var fileMock = new Mock<IFormFile>();
             fileMock.Setup(f => f.FileName).Returns("large.png");
             fileMock.Setup(f => f.Length).Returns(10 * 1024 * 1024);

             var result = _controller.Edit(course, fileMock.Object);

             var viewResult = Assert.IsType<ViewResult>(result);
             Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
         }

         [Fact]
         public void Delete_GET_WithValidId_ReturnsViewResult()
         {
             TestHelpers.SeedCourses(_context);
             var course = _context.Courses.First();

             var result = _controller.Delete(course.CourseID);

             var viewResult = Assert.IsType<ViewResult>(result);
             var model = Assert.IsType<Course>(viewResult.Model);
             Assert.Equal(course.CourseID, model.CourseID);
         }

         [Fact]
         public void Delete_GET_WithNullId_ReturnsBadRequest()
         {
             var result = _controller.Delete(null);

             var statusResult = Assert.IsType<StatusCodeResult>(result);
             Assert.Equal(400, statusResult.StatusCode);
         }

         [Fact]
         public void DeleteConfirmed_RemovesCourse_RedirectsToIndex()
         {
             TestHelpers.SeedCourses(_context);
             var course = _context.Courses.First();
             var originalCount = _context.Courses.Count();

             var result = _controller.DeleteConfirmed(course.CourseID);

             var redirectResult = Assert.IsType<RedirectToActionResult>(result);
             Assert.Equal("Index", redirectResult.ActionName);
             Assert.Equal(originalCount - 1, _context.Courses.Count());
         }

         [Fact]
         public void DeleteConfirmed_RemovesCorrectCourse()
         {
             TestHelpers.SeedCourses(_context);
             var course = _context.Courses.First();

             _controller.DeleteConfirmed(course.CourseID);

             Assert.Null(_context.Courses.Find(course.CourseID));
         }

         [Theory]
         [InlineData(".jpg")]
         [InlineData(".jpeg")]
         [InlineData(".png")]
         [InlineData(".gif")]
         [InlineData(".bmp")]
         public void Create_POST_AllowedImageExtensions_AreAccepted(string extension)
         {
             TestHelpers.SeedDepartments(_context);
             var courseId = 3000 + Math.Abs(extension.GetHashCode() % 1000);
             var course = new Course
             {
                 CourseID = courseId,
                 Title = $"Course {extension}",
                 Credits = 3,
                 DepartmentID = 1
             };

             var fileMock = new Mock<IFormFile>();
             fileMock.Setup(f => f.FileName).Returns($"test{extension}");
             fileMock.Setup(f => f.Length).Returns(1024);
             fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

             var result = _controller.Create(course, fileMock.Object);

             Assert.IsType<RedirectToActionResult>(result);
         }

         public void Dispose()
         {
             _controller.Dispose();
             _context.Dispose();
             try
             {
                 if (Directory.Exists(_testWebRoot))
                     Directory.Delete(_testWebRoot, true);
             }
             catch { }
         }
     }
 }

