 using Xunit;

 namespace ContosoUniversity.Tests.Controllers
 {
     public class NotificationsControllerTests : IDisposable
     {
         private readonly SchoolContext _context;
         private readonly NotificationsController _controller;

         public NotificationsControllerTests()
         {
             _context = TestHelpers.CreateInMemoryContext();
             _controller = new NotificationsController(_context);

             // Drain queue
             using var tempService = new NotificationService();
             while (tempService.ReceiveNotification() != null) { }
         }

         [Fact]
         public void Index_ReturnsViewResult()
         {
             var result = _controller.Index();

             Assert.IsType<ViewResult>(result);
         }

         [Fact]
         public void GetNotifications_WhenQueueEmpty_ReturnsSuccessWithEmptyList()
         {
             var result = _controller.GetNotifications();

             Assert.IsType<JsonResult>(result);
             var value = result.Value;
             Assert.NotNull(value);

             // Check via reflection for the success property
             var successProp = value.GetType().GetProperty("success");
             Assert.NotNull(successProp);
             Assert.True((bool)successProp.GetValue(value)!);

             var countProp = value.GetType().GetProperty("count");
             Assert.NotNull(countProp);
             Assert.Equal(0, (int)countProp.GetValue(value)!);
         }

         [Fact]
         public void GetNotifications_WhenNotificationsExist_ReturnsThem()
         {
             // Send some notifications via the controller's inherited notificationService
             _controller.notificationService.SendNotification("Student", "1", "John", EntityOperation.CREATE);
             _controller.notificationService.SendNotification("Course", "2", "Math", EntityOperation.UPDATE);

             var result = _controller.GetNotifications();

             Assert.IsType<JsonResult>(result);
             var value = result.Value;
             Assert.NotNull(value);

             var countProp = value.GetType().GetProperty("count");
             Assert.NotNull(countProp);
             Assert.Equal(2, (int)countProp.GetValue(value)!);
         }

         [Fact]
         public void GetNotifications_LimitsTo10Notifications()
         {
             // Send 15 notifications
             for (int i = 0; i < 15; i++)
             {
                 _controller.notificationService.SendNotification("Test", i.ToString(), $"Entity{i}", EntityOperation.CREATE);
             }

             var result = _controller.GetNotifications();

             var value = result.Value;
             Assert.NotNull(value);

             var countProp = value.GetType().GetProperty("count");
             Assert.NotNull(countProp);
             Assert.Equal(10, (int)countProp.GetValue(value)!);
         }

         [Fact]
         public void MarkAsRead_ReturnsSuccessJson()
         {
             var result = _controller.MarkAsRead(1);

             Assert.IsType<JsonResult>(result);
             var value = result.Value;
             Assert.NotNull(value);

             var successProp = value.GetType().GetProperty("success");
             Assert.NotNull(successProp);
             Assert.True((bool)successProp.GetValue(value)!);
         }

         [Fact]
         public void MarkAsRead_WithAnyId_ReturnsSuccess()
         {
             var result = _controller.MarkAsRead(999);

             Assert.IsType<JsonResult>(result);
             var value = result.Value;
             Assert.NotNull(value);

             var successProp = value.GetType().GetProperty("success");
             Assert.NotNull(successProp);
             Assert.True((bool)successProp.GetValue(value)!);
         }

         [Fact]
         public void GetNotifications_AfterDrainingQueue_ReturnsEmptyOnSecondCall()
         {
             _controller.notificationService.SendNotification("Test", "1", "Entity", EntityOperation.CREATE);

             var first = _controller.GetNotifications();
             var second = _controller.GetNotifications();

             var secondValue = second.Value;
             Assert.NotNull(secondValue);
             var countProp = secondValue.GetType().GetProperty("count");
             Assert.NotNull(countProp);
             Assert.Equal(0, (int)countProp.GetValue(secondValue)!);
         }

         public void Dispose()
         {
             // Drain remaining notifications
             while (_controller.notificationService.ReceiveNotification() != null) { }
             _controller.Dispose();
             _context.Dispose();
         }
     }
 }

