            _controller.TempData = new TempDataDictionary(httpContext, new Mock<ITempDataProvider>().Object);
        }

        [Fact]
        public void Create_POST_FileExactly5MB_IsAccepted()
        {
            TestHelpers.SeedDepartments(_context);
            var course = new Course { CourseID = 4444, Title = "Exact5MB", Credits = 3, DepartmentID = 1 };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("exact.jpg");
            fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024); // Exactly 5MB
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, fileMock.Object);

            // 5MB should be accepted (> check, not >=)
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_FileOneByteOver5MB_IsRejected()
        {
            TestHelpers.SeedDepartments(_context);
            var course = new Course { CourseID = 4445, Title = "Over5MB", Credits = 3, DepartmentID = 1 };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("large.jpg");
            fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024 + 1); // 5MB + 1 byte

            var result = _controller.Create(course, fileMock.Object);

            Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_POST_FileExactly5MB_IsAccepted()
        {
            TestHelpers.SeedCourses(_context);
            var original = _context.Courses.First();
            var courseId = original.CourseID;
            var deptId = original.DepartmentID;
            _context.Entry(original).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var course = new Course { CourseID = courseId, Title = "Edit5MB", Credits = 3, DepartmentID = deptId };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("exact.png");
            fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Edit(course, fileMock.Object);

            Assert.IsType<RedirectToActionResult>(result);
        }

        [Fact]
        public void Edit_POST_FileOneByteOver5MB_IsRejected()
        {
            TestHelpers.SeedCourses(_context);
            var original = _context.Courses.First();
            var courseId = original.CourseID;
            var deptId = original.DepartmentID;
            _context.Entry(original).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var course = new Course { CourseID = courseId, Title = "EditOver5MB", Credits = 3, DepartmentID = deptId };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("large.png");
            fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024 + 1);

            var result = _controller.Edit(course, fileMock.Object);

            Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_POST_ZeroLengthFile_IsNotProcessedAsImage()
        {
            TestHelpers.SeedDepartments(_context);
            var course = new Course { CourseID = 3333, Title = "ZeroFile", Credits = 3, DepartmentID = 1 };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("empty.jpg");
            fileMock.Setup(f => f.Length).Returns(0); // Zero length

            var result = _controller.Create(course, fileMock.Object);

            // Zero-length file should be treated as "no file" (Length > 0 check)
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_ValidFile_SetsTeachingMaterialImagePath()
        {
            TestHelpers.SeedDepartments(_context);
            var course = new Course { CourseID = 2222, Title = "PathTest", Credits = 3, DepartmentID = 1 };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("material.png");
            fileMock.Setup(f => f.Length).Returns(1024);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            _controller.Create(course, fileMock.Object);

            var saved = _context.Courses.Find(2222);
            Assert.NotNull(saved);
            Assert.NotNull(saved.TeachingMaterialImagePath);
            Assert.StartsWith("/Uploads/TeachingMaterials/course_2222_", saved.TeachingMaterialImagePath);
            Assert.EndsWith(".png", saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void DeleteConfirmed_CourseWithImage_DeletesImageFile()
        {
            TestHelpers.SeedCourses(_context);
            var course = _context.Courses.First();

            // Create a fake image file
            var uploadsDir = Path.Combine(_testWebRoot, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(uploadsDir);
            var imageFile = Path.Combine(uploadsDir, "test_image.jpg");
            File.WriteAllText(imageFile, "fake");
            course.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/test_image.jpg";
            _context.SaveChanges();

            _controller.DeleteConfirmed(course.CourseID);

            Assert.False(File.Exists(imageFile));
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            try { if (Directory.Exists(_testWebRoot)) Directory.Delete(_testWebRoot, true); } catch { }
        }
    }
