using System;
using System.IO;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    /// <summary>
    /// Boundary and edge case tests for CoursesController file upload logic.
    /// </summary>
    public class CoursesControllerBoundaryTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _envMock;
        private readonly string _testWebRoot;

        public CoursesControllerBoundaryTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
            _envMock = new Mock<IWebHostEnvironment>();
            var loggerMock = new Mock<ILogger<CoursesController>>();
            _testWebRoot = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(_testWebRoot);
            _envMock.Setup(e => e.WebRootPath).Returns(_testWebRoot);
            _envMock.Setup(e => e.ContentRootPath).Returns(_testWebRoot);

            _controller = new CoursesController(_context, _envMock.Object, loggerMock.Object);
            var httpContext = new DefaultHttpContext();
            _controller.TempData = new TempDataDictionary(httpContext, new Mock<ITempDataProvider>().Object);
        }

        [Fact]
        public void Create_POST_FileExactly5MB_IsAccepted()
        {
            TestHelpers.SeedDepartments(_context);
            var course = new Course { CourseID = 4444, Title = "Exact5MB", Credits = 3, DepartmentID = 1 };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("exact.jpg");
            fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024); // Exactly 5MB
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, fileMock.Object);

            // 5MB should be accepted (> check, not >=)
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_FileOneByteOver5MB_IsRejected()
        {
            TestHelpers.SeedDepartments(_context);
            var course = new Course { CourseID = 4445, Title = "Over5MB", Credits = 3, DepartmentID = 1 };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("large.jpg");
            fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024 + 1); // 5MB + 1 byte

            var result = _controller.Create(course, fileMock.Object);

            Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_POST_FileExactly5MB_IsAccepted()
        {
            TestHelpers.SeedCourses(_context);
            var original = _context.Courses.First();
            var courseId = original.CourseID;
            var deptId = original.DepartmentID;
            _context.Entry(original).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var course = new Course { CourseID = courseId, Title = "Edit5MB", Credits = 3, DepartmentID = deptId };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("exact.png");
            fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Edit(course, fileMock.Object);

            Assert.IsType<RedirectToActionResult>(result);
        }

        [Fact]
        public void Edit_POST_FileOneByteOver5MB_IsRejected()
        {
            TestHelpers.SeedCourses(_context);
            var original = _context.Courses.First();
            var courseId = original.CourseID;
            var deptId = original.DepartmentID;
            _context.Entry(original).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var course = new Course { CourseID = courseId, Title = "EditOver5MB", Credits = 3, DepartmentID = deptId };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("large.png");
            fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024 + 1);

            var result = _controller.Edit(course, fileMock.Object);

            Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_POST_ZeroLengthFile_IsNotProcessedAsImage()
        {
            TestHelpers.SeedDepartments(_context);
            var course = new Course { CourseID = 3333, Title = "ZeroFile", Credits = 3, DepartmentID = 1 };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("empty.jpg");
            fileMock.Setup(f => f.Length).Returns(0); // Zero length

            var result = _controller.Create(course, fileMock.Object);

            // Zero-length file should be treated as "no file" (Length > 0 check)
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_ValidFile_SetsTeachingMaterialImagePath()
        {
            TestHelpers.SeedDepartments(_context);
            var course = new Course { CourseID = 2222, Title = "PathTest", Credits = 3, DepartmentID = 1 };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("material.png");
            fileMock.Setup(f => f.Length).Returns(1024);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            _controller.Create(course, fileMock.Object);

            var saved = _context.Courses.Find(2222);
            Assert.NotNull(saved);
            Assert.NotNull(saved.TeachingMaterialImagePath);
            Assert.StartsWith("/Uploads/TeachingMaterials/course_2222_", saved.TeachingMaterialImagePath);
            Assert.EndsWith(".png", saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void DeleteConfirmed_CourseWithImage_DeletesImageFile()
        {
            TestHelpers.SeedCourses(_context);
            var course = _context.Courses.First();

            // Create a fake image file
            var uploadsDir = Path.Combine(_testWebRoot, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(uploadsDir);
            var imageFile = Path.Combine(uploadsDir, "test_image.jpg");
            File.WriteAllText(imageFile, "fake");
            course.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/test_image.jpg";
            _context.SaveChanges();

            _controller.DeleteConfirmed(course.CourseID);

            Assert.False(File.Exists(imageFile));
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            try { if (Directory.Exists(_testWebRoot)) Directory.Delete(_testWebRoot, true); } catch { }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Utilities
{
    /// <summary>
    /// Boundary tests to strengthen mutation resistance for PaginatedList.
    /// </summary>
    public class PaginatedListBoundaryTests
    {
        [Fact]
        public void HasPreviousPage_PageZero_ReturnsFalse()
        {
            // PageIndex 0 should return false (0 > 1 is false)
            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 0, 5);
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_PageOne_ReturnsFalse()
        {
            // PageIndex 1: 1 > 1 is false
            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_PageTwo_ReturnsTrue()
        {
            // PageIndex 2: 2 > 1 is true
            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);
            Assert.True(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_OnLastPage_ReturnsFalse()
        {
            // 10 items, 5 per page = 2 pages. On page 2: 2 < 2 is false
            var list = new PaginatedList<int>(new List<int> { 6, 7, 8, 9, 10 }, 10, 2, 5);
            Assert.Equal(2, list.PageIndex);
            Assert.Equal(2, list.TotalPages);
            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_OnFirstOfTwoPages_ReturnsTrue()
        {
            // 10 items, 5 per page = 2 pages. On page 1: 1 < 2 is true
            var list = new PaginatedList<int>(new List<int> { 1, 2, 3, 4, 5 }, 10, 1, 5);
            Assert.Equal(1, list.PageIndex);
            Assert.Equal(2, list.TotalPages);
            Assert.True(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_SinglePage_ReturnsFalse()
        {
            // 3 items, 5 per page = 1 page. On page 1: 1 < 1 is false
            var list = new PaginatedList<int>(new List<int> { 1, 2, 3 }, 3, 1, 5);
            Assert.Equal(1, list.PageIndex);
            Assert.Equal(1, list.TotalPages);
            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void TotalPages_NonDivisibleCount_RoundsUp()
        {
            // 11 items, 5 per page => ceil(11/5) = ceil(2.2) = 3
            var list = new PaginatedList<int>(new List<int>(), 11, 1, 5);
            Assert.Equal(3, list.TotalPages);
        }

        [Fact]
        public void TotalPages_ExactlyDivisible_NoRoundUp()
        {
            // 10 items, 5 per page => ceil(10/5) = 2
            var list = new PaginatedList<int>(new List<int>(), 10, 1, 5);
            Assert.Equal(2, list.TotalPages);
        }

        [Fact]
        public void TotalPages_OneItem_IsOnePage()
        {
            var list = new PaginatedList<int>(new List<int> { 1 }, 1, 1, 10);
            Assert.Equal(1, list.TotalPages);
        }

        [Fact]
        public void TotalPages_ZeroItems_IsZeroPages()
        {
            var list = new PaginatedList<int>(new List<int>(), 0, 1, 10);
            Assert.Equal(0, list.TotalPages);
        }

        [Fact]
        public void Create_SkipsCorrectNumberOfItems()
        {
            var source = Enumerable.Range(1, 10).AsQueryable();

            // Page 2 with pageSize 3: skip 3, take 3 => items 4, 5, 6
            var result = PaginatedList<int>.Create(source, 2, 3);

            Assert.Equal(3, result.Count);
            Assert.Equal(4, result[0]);
            Assert.Equal(5, result[1]);
            Assert.Equal(6, result[2]);
        }

        [Fact]
        public void Create_Page3_SkipsCorrectly()
        {
            var source = Enumerable.Range(1, 15).AsQueryable();

            // Page 3 with pageSize 4: skip 8, take 4 => items 9, 10, 11, 12
            var result = PaginatedList<int>.Create(source, 3, 4);

            Assert.Equal(4, result.Count);
            Assert.Equal(9, result[0]);
            Assert.Equal(12, result[3]);
        }

        [Theory]
        [InlineData(7, 3, 3)]   // 7/3 = ceil(2.33) = 3
        [InlineData(1, 1, 1)]   // 1/1 = 1
        [InlineData(5, 2, 3)]   // 5/2 = ceil(2.5) = 3
        [InlineData(99, 10, 10)] // 99/10 = ceil(9.9) = 10
        public void TotalPages_VariousCounts_CalculatesCorrectly(int count, int pageSize, int expectedTotalPages)
        {
            var list = new PaginatedList<int>(new List<int>(), count, 1, pageSize);
            Assert.Equal(expectedTotalPages, list.TotalPages);
        }
    }
}

